@startuml
class City {
  +name : string
  +inhabitants : int
}
class Attraction {
  +name : string
  +address : string
}
class GuidedTour {
  +duration : int
  +number : int
}
class Visitor {
  +name : string
}
class Guide {
  +name : string
}
class Person {}
class Discount {
  +amount : float
}

Person <|-- Visitor
Person <|-- Guide

City "1" -- "*" Attraction : has
Attraction "1" -- "*" GuidedTour : offers
GuidedTour "1" -- "1" Guide : requires
GuidedTour "0..20" -- "*" Visitor : takes part in
Visitor "0..*" -- "0..*" GuidedTour : receives
(Visitor, GuidedTour) .. Discount
@enduml

